-- Resources content for stackable broadcast roles (CLAUDE.md, "Resources
-- stay in step with the code"). Content only; the schema change is
-- 20261002150000. docs/broadcast-roles.md is the reference.

select private.rc_release_guide(
  p_slug => 'log-dad-log',
  p_tool_key => 'log',
  p_title => 'The DAD log',
  p_summary => 'The file DAD plays automated hours from: what''s in it, what stops it, and how to release it.',
  p_screen_keys => array['log.dad-log'],
  p_sort_order => 46,
  p_version_note => 'Traffic releases the DAD log',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The DAD log is the file DAD merges into a day's playlist so it plays that day's credits in automated hours. Open it from "},{"type":"text","text":"Today","marks":[{"type":"bold"}]},{"type":"text","text":" with "},{"type":"text","text":"DAD log","marks":[{"type":"bold"}]},{"type":"text","text":". Only breaks in automated hours are in the file; hosted hours are left to the host."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Before releasing"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The bar at the top shades the day's automated hours. Change them on "},{"type":"text","text":"Automated hours","marks":[{"type":"bold"}]},{"type":"text","text":", reached from Programs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anything DAD can't play is listed first, with a link to fix it: a message with no DAD cut, something only a host can do (a live read written for the rundown, or the weather), copy that isn't approved or is outside its dates, or a break that runs past its window."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A program that airs in automated hours but has no rundown is listed as worth knowing. Its breaks aren't in the file until it has one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Table","marks":[{"type":"bold"}]},{"type":"text","text":" shows what DAD will play and when. "},{"type":"text","text":"File","marks":[{"type":"bold"}]},{"type":"text","text":" shows the exact rows."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Releasing"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Traffic releases the day with "},{"type":"text","text":"Release","marks":[{"type":"bold"}]},{"type":"text","text":". It's refused while anything can't play."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Download the release and put it in DAD's import folder. The file is named for the day, such as 100126tWUWF.log."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If a rundown changes afterwards, the page says the release is out of date. Release again; each release is a new version, and the history keeps every one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each item keeps the same spot number in every version."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-automated-hours',
  p_tool_key => 'log',
  p_title => 'Automated hours',
  p_summary => 'When no one is in the studio: weekly automated hours and one-time changes, and what they mean for credits.',
  p_screen_keys => array['log.automated-hours'],
  p_sort_order => 45,
  p_version_note => 'The program director changes automated hours',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every hour is hosted unless it's listed on this page. In automated hours no one is in the studio, so DAD plays that hour's underwriting credits. Open it from "},{"type":"text","text":"Programs","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Weekly hours"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"+ Weekly hours","marks":[{"type":"bold"}]},{"type":"text","text":" for the routine ones, such as overnights from 8:00 PM to 5:00 AM. Pick the days, the times, and the date they start."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An end time at or before the start runs past midnight. The early-morning part belongs to the day the hours started, so Saturday 8:00 PM – 5:00 AM covers early Sunday."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Weekly hours can cover a whole program or just some of its hours. The "},{"type":"text","text":"Programs in these hours","marks":[{"type":"bold"}]},{"type":"text","text":" column shows what's on the air then."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"One-time changes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"+ One-time change","marks":[{"type":"bold"}]},{"type":"text","text":" for a holiday, a host out, or a special. Choose "},{"type":"text","text":"Automated","marks":[{"type":"bold"}]},{"type":"text","text":" to automate hours that are normally hosted, or "},{"type":"text","text":"Live","marks":[{"type":"bold"}]},{"type":"text","text":" to host hours that are normally automated."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A one-time change wins over the weekly hours. One-time changes can't overlap each other."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Midnight to midnight covers whole days: Thanksgiving is Thursday 12:00 AM until Friday 12:00 AM."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Week and month"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The week view draws each day's automated hours over the programs on the air. Grey is weekly, dashed amber is automated once, and dashed blue is live once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The month view shows each day's automated hours. Pick a day to see its week."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A credit in automated hours needs copy with a DAD cut, since DAD plays it. A live read qualifies through its recorded version. Auto-fill leaves those breaks to copy that has one, and placing cut-less copy there is refused."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only the program director can change automated hours. Nothing is deleted: removing hours or a change takes it off the schedule."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-02-log-broadcast-roles',
  p_tool_key => 'log',
  p_released_on => '2026-10-02',
  p_title => 'Program director, traffic, and production roles',
  p_guide_slugs => array['log-dad-log', 'log-automated-hours'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The producer role is split by job. The program director edits clocks, the program schedule, programs, and automated hours. Traffic pins station IDs and releases the DAD log. In Underwriting & Traffic, a new production role is for whoever records messages into DAD. A person can hold any combination, and an administrator now picks them with checkboxes on the user's access page. Everyone who was a producer holds both the program director and traffic roles, and every underwriting manager also holds production."}]}]}$body$
);
